cd C:/Users/user/AppData/Local/Temp/skill-eval-mxFpJn && mkdir -p out && ls node_modules/es-toolkit/dist/math | grep sumBy.js; ls node_modules/es-toolkit/dist/compat/*/fromPairs.js node_modules/es-toolkit/dist/compat/*/sumBy.js
cat > out/a.ts <<'E'
import { pick, zipObject } from 'es-toolkit';
import { sumBy, unzip } from 'es-toolkit';
export interface Row { id: number; name: string; age: number; }
export type Config = Record<string, unknown>;
export function publicFields(row: Row): Pick<Row, 'id' | 'name'> { return pick(row, ['id', 'name']); }
export function totalAge(rows: Row[]): number { return sumBy(rows, (r) => r.age); }
export function toLookup(pairs: [string, number][]): Record<string, number> {
  const [k = [], v = []] = unzip(pairs);
  return zipObject(k as string[], v as number[]);
}
E
cat > out/b.ts <<'E'
import { pick, sumBy } from 'es-toolkit';
import { fromPairs } from 'es-toolkit/compat';
export interface Row { id: number; name: string; age: number; }
export type Config = Record<string, unknown>;
export function publicFields(row: Row): Pick<Row, 'id' | 'name'> { return pick(row, ['id', 'name']); }
export function totalAge(rows: Row[]): number { return sumBy(rows, (r) => r.age); }
export function toLookup(pairs: [string, number][]): Record<string, number> { return fromPairs(pairs); }
E
npm run size -- out/a.ts; npm run size -- out/b.ts; npm run size -- src/module.ts

